-- PostgreSQL baseline for the SQLite schema version 12.
CREATE TABLE IF NOT EXISTS schema_migrations (version integer PRIMARY KEY);
CREATE TABLE IF NOT EXISTS organizations (id text PRIMARY KEY, name text NOT NULL, created_at text NOT NULL, updated_at text NOT NULL);
CREATE TABLE IF NOT EXISTS accounts (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), login text NOT NULL UNIQUE, display_name text NOT NULL, role text NOT NULL, password_salt text NOT NULL, password_hash text NOT NULL, password_cost integer NOT NULL, password_block_size integer NOT NULL, password_parallelization integer NOT NULL, status text NOT NULL, created_at text NOT NULL, updated_at text NOT NULL, must_change_password boolean NOT NULL DEFAULT false, capabilities_json jsonb NOT NULL DEFAULT '[]'::jsonb, custom_role_json jsonb);
CREATE TABLE IF NOT EXISTS sessions (id text PRIMARY KEY, token_hash text NOT NULL UNIQUE, account_id text NOT NULL REFERENCES accounts(id) ON DELETE CASCADE, created_at text NOT NULL, last_used_at text NOT NULL, expires_at text NOT NULL, revoked_at text);
CREATE TABLE IF NOT EXISTS ai_uses (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), created_by_account_id text REFERENCES accounts(id), name text NOT NULL, purpose text NOT NULL, owner text NOT NULL, business_area text NOT NULL, data_description text NOT NULL, data_sensitivity text NOT NULL, approval_status text NOT NULL, source text NOT NULL, created_at text NOT NULL, updated_at text NOT NULL);
CREATE TABLE IF NOT EXISTS governance_actions (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), ai_use_id text NOT NULL REFERENCES ai_uses(id), assessment_id text, title text NOT NULL, owner text NOT NULL, due_date text NOT NULL, status text NOT NULL, version integer NOT NULL, created_at text NOT NULL, updated_at text NOT NULL, completed_at text, history_json jsonb NOT NULL, owner_account_id text REFERENCES accounts(id));
CREATE TABLE IF NOT EXISTS organization_settings (organization_id text PRIMARY KEY REFERENCES organizations(id), appearance text NOT NULL, updated_at text NOT NULL);
CREATE TABLE IF NOT EXISTS account_audit (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), actor_id text NOT NULL REFERENCES accounts(id), account_id text NOT NULL REFERENCES accounts(id), action text NOT NULL, created_at text NOT NULL);
CREATE TABLE IF NOT EXISTS assessments (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), ai_use_id text NOT NULL REFERENCES ai_uses(id), created_by text NOT NULL REFERENCES accounts(id), state text NOT NULL, revision integer NOT NULL, definition_json jsonb NOT NULL, responses_json jsonb NOT NULL, result_json jsonb, created_at text NOT NULL, updated_at text NOT NULL);
CREATE TABLE IF NOT EXISTS policies (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), document_id text NOT NULL, version integer NOT NULL, title text NOT NULL, filename text NOT NULL, media_type text NOT NULL, content bytea NOT NULL, sha256 text NOT NULL, checklist_json jsonb NOT NULL, reviewer_id text NOT NULL REFERENCES accounts(id), review_due text NOT NULL, reviewed_at text, created_by text NOT NULL REFERENCES accounts(id), created_at text NOT NULL, UNIQUE (organization_id,document_id,version));
CREATE TABLE IF NOT EXISTS reminder_settings (organization_id text PRIMARY KEY REFERENCES organizations(id), enabled boolean NOT NULL, upcoming_days integer NOT NULL, repeat_days integer NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), account_id text NOT NULL REFERENCES accounts(id), dedupe_key text NOT NULL UNIQUE, kind text NOT NULL, item_id text NOT NULL, title text NOT NULL, message text NOT NULL, delivered_at text NOT NULL, read_at text);
CREATE TABLE IF NOT EXISTS reminder_runs (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, started_at text NOT NULL, status text NOT NULL, delivered integer NOT NULL, error text);
CREATE TABLE IF NOT EXISTS registry_events (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), ai_use_id text NOT NULL REFERENCES ai_uses(id), actor_id text NOT NULL REFERENCES accounts(id), changes_json jsonb NOT NULL, created_at text NOT NULL);
CREATE TABLE IF NOT EXISTS governance_configurations (organization_id text NOT NULL REFERENCES organizations(id), version integer NOT NULL, configuration_json jsonb NOT NULL, actor_id text NOT NULL REFERENCES accounts(id), created_at text NOT NULL, PRIMARY KEY (organization_id,version));
CREATE TABLE IF NOT EXISTS configuration_events (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), version integer NOT NULL, action text NOT NULL, actor_id text NOT NULL REFERENCES accounts(id), reference text NOT NULL, created_at text NOT NULL);
CREATE TABLE IF NOT EXISTS policy_acknowledgements (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), assessment_id text NOT NULL REFERENCES assessments(id), policy_id text NOT NULL REFERENCES policies(id), account_id text NOT NULL REFERENCES accounts(id), sha256 text NOT NULL, acknowledged_at text NOT NULL, UNIQUE (assessment_id,policy_id,account_id));
CREATE TABLE IF NOT EXISTS reporting_coverage (organization_id text PRIMARY KEY REFERENCES organizations(id), started_at text NOT NULL);
CREATE TABLE IF NOT EXISTS reporting_history (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), entity text NOT NULL, record_id text NOT NULL, record_json jsonb NOT NULL, recorded_at text NOT NULL, deleted boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ai_uses_organization ON ai_uses(organization_id);
CREATE INDEX IF NOT EXISTS ai_uses_business_area ON ai_uses(organization_id,business_area);
CREATE INDEX IF NOT EXISTS sessions_account ON sessions(account_id);
CREATE INDEX IF NOT EXISTS governance_actions_organization ON governance_actions(organization_id,ai_use_id);
CREATE INDEX IF NOT EXISTS assessments_scope ON assessments(organization_id,ai_use_id,updated_at);
CREATE INDEX IF NOT EXISTS reporting_history_cutoff ON reporting_history(organization_id,entity,recorded_at,record_id);
